const repo = $env.GITHUB_REPO || 'anthropics/claude-code';
const language = ($env.SUMMARY_LANGUAGE || 'EN').toUpperCase();
const githubToken = $env.GITHUB_TOKEN;
const anthropicKey = $env.ANTHROPIC_API_KEY;

if (!repo.includes('/')) {
  throw new Error('GITHUB_REPO must use the owner/name format, for example anthropics/claude-code');
}
if (!anthropicKey) {
  throw new Error('ANTHROPIC_API_KEY is required');
}

const [owner, name] = repo.split('/');
const until = new Date();
const since = new Date(until);
since.setUTCDate(since.getUTCDate() - 7);

const githubHeaders = {
  Accept: 'application/vnd.github+json',
  'User-Agent': 'n8n-claude-weekly-summary'
};
if (githubToken) {
  githubHeaders.Authorization = `Bearer ${githubToken}`;
}

async function github(path) {
  return await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com${path}`,
    headers: githubHeaders,
    json: true
  });
}

const encodedRepo = `${encodeURIComponent(owner)}/${encodeURIComponent(name)}`;
const sinceIso = since.toISOString();
const untilIso = until.toISOString();

const [commits, closedIssues, closedPulls] = await Promise.all([
  github.call(this, `/repos/${encodedRepo}/commits?since=${encodeURIComponent(sinceIso)}&until=${encodeURIComponent(untilIso)}&per_page=100`),
  github.call(this, `/repos/${encodedRepo}/issues?state=closed&since=${encodeURIComponent(sinceIso)}&per_page=100`),
  github.call(this, `/repos/${encodedRepo}/pulls?state=closed&sort=updated&direction=desc&per_page=100`)
]);

const inWindow = (value) => {
  if (!value) return false;
  const date = new Date(value);
  return date >= since && date <= until;
};

const normalizedCommits = commits.map((commit) => ({
  sha: commit.sha?.slice(0, 7),
  message: commit.commit?.message?.split('\n')[0] || '',
  author: commit.commit?.author?.name || commit.author?.login || 'unknown',
  url: commit.html_url
}));

const normalizedIssues = closedIssues
  .filter((issue) => !issue.pull_request && inWindow(issue.closed_at))
  .map((issue) => ({
    number: issue.number,
    title: issue.title,
    author: issue.user?.login || 'unknown',
    url: issue.html_url
  }));

const normalizedPulls = closedPulls
  .filter((pull) => inWindow(pull.merged_at))
  .map((pull) => ({
    number: pull.number,
    title: pull.title,
    author: pull.user?.login || 'unknown',
    url: pull.html_url
  }));

const summaryInput = {
  repository: repo,
  window: { since: sinceIso, until: untilIso },
  totals: {
    commits: normalizedCommits.length,
    closedIssues: normalizedIssues.length,
    mergedPullRequests: normalizedPulls.length
  },
  commits: normalizedCommits.slice(0, 40),
  closedIssues: normalizedIssues.slice(0, 40),
  mergedPullRequests: normalizedPulls.slice(0, 40)
};

const prompt = `Write a concise weekly narrative engineering summary in ${language === 'FR' ? 'French' : 'English'} for this GitHub repository activity. Focus on what changed, why it matters, notable themes, and suggested next steps. Use Markdown with short sections.\n\n${JSON.stringify(summaryInput, null, 2)}`;

const claudeResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.anthropic.com/v1/messages',
  headers: {
    'content-type': 'application/json',
    'anthropic-version': '2023-06-01',
    'x-api-key': anthropicKey
  },
  body: {
    model: 'claude-sonnet-4-20250514',
    max_tokens: 1400,
    messages: [
      {
        role: 'user',
        content: prompt
      }
    ]
  },
  json: true
});

const summary = claudeResponse.content
  ?.map((part) => part.type === 'text' ? part.text : '')
  .join('\n')
  .trim();

if (!summary) {
  throw new Error('Claude returned an empty summary');
}

const header = `Weekly GitHub summary for ${repo} (${sinceIso.slice(0, 10)} to ${untilIso.slice(0, 10)})`;
const discordContent = `**${header}**\n\n${summary}`.slice(0, 1900);

return [
  {
    json: {
      repo,
      language,
      since: sinceIso,
      until: untilIso,
      totals: summaryInput.totals,
      summary,
      discordPayload: {
        content: discordContent
      }
    }
  }
];
